#pragma once

// Binds the semantic project document to the current workspace. In managed
// mode the local store commits this document independently of Orca's model;
// attachment bytes live under the same stable project ID. External 3MF files
// are imports/exports and do not carry the managed conversation. The old
// auxiliary state and newer recovery mirror are read once during migration.
// A configuration without managed_root retains the legacy contract for older
// hosts and its focused tests.
//
// Project boundaries follow the auxiliary directory: it changes whenever the
// authoritative project is replaced by a load or a new project, and stays
// put on an in-place full reset — which per the product rules starts a new
// project identity. GUI-free; the owner drives flushing from its timer.

#include "ProjectStateDocument.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <cstdint>
#include <functional>
#include <map>
#include <memory>
#include <string>

namespace Slic3r::GUI::JusPrin::Agent {

class ProjectPersistence
{
public:
    struct Config
    {
        // Managed projects keep semantic state beside their version store.
        // Empty preserves the legacy auxiliary/recovery behavior for tests
        // and older hosts that have not installed the local version store.
        std::string managed_root;
        // Root directory of the local recovery store; empty disables it.
        std::string recovery_root;
        // Injectable for deterministic tests.
        std::function<std::string()> clock; // ISO-8601 UTC timestamp
        std::function<std::string()> uuid;  // opaque unique identifier
        // A conversation about something other than the open project -- the
        // temporary task chat -- keeps everything in memory: nothing it
        // says belongs in this project's archive, and the session is gone
        // when the panel closes. Such an instance follows no project
        // boundary, writes no state.json and no recovery mirror, and holds
        // attachment bytes for its own lifetime only.
        bool in_memory{false};
    };

    ProjectPersistence(Workspace::IWorkspace& workspace, Config config);

    ProjectPersistence(const ProjectPersistence&) = delete;
    ProjectPersistence& operator=(const ProjectPersistence&) = delete;

    // Adopts the currently open project (call once after construction; later
    // project replacements are adopted automatically via workspace events).
    void attach();

    // A Project change whose auxiliary dir has not moved yet is ambiguous:
    // an in-place full reset, or a replacement whose event was published
    // before the new directory was adopted (Plater does both). The decision
    // is parked and resolved here once the directory has settled — the owner
    // calls this from its pacing timer; later workspace events and flushes
    // resolve it too.
    void resolve_pending_boundary();
    // Orca emits project-boundary events while loading a historical model.
    // The caller restores the existing managed identity when the load ends.
    void during_managed_restore(const std::function<void()>& operation);

    ProjectStateDocument&       document() { return m_document; }
    const ProjectStateDocument& document() const { return m_document; }

    // The configured clock, for consumers stamping document entries.
    std::string timestamp() const { return m_config.clock(); }

    // Fired after the document has been replaced by an adoption; the consumer
    // must rebuild everything it derived from the old document.
    void set_document_replaced_listener(std::function<void()> listener) { m_document_replaced = std::move(listener); }
    // Fired after each workspace edit has been appended to the change log.
    void set_change_listener(std::function<void(const ChangeEntry&)> listener) { m_change_added = std::move(listener); }

    // Fired when the manufacturing ledger gains an entry or the document is
    // replaced. Any number of shell surfaces may observe it -- the Project
    // pane's print history, the status row's overflow menu -- each holding its
    // own subscription; dropping one never affects another.
    Workspace::WorkspaceSubscription subscribe_ledger(std::function<void()> listener);
    void notify_ledger_changed() const;

    // Marks the document changed. In managed mode ProjectAutosave coalesces
    // document writes between model versions; legacy mode flushes auxiliary files.
    void commit() { m_dirty = true; }
    void flush();
    void flush_if_dirty();
    void record_managed_restore(const std::string& current_state, const std::string& from_version,
                                const std::string& selected_version);
    void adopt_managed_state(const std::string& state);

    // The composer draft is a document field in managed mode; legacy mode
    // continues to keep it in the recovery mirror.
    void               set_draft(const std::string& text);
    const std::string& draft() const { return m_draft; }

    // -- Attachment blobs ---------------------------------------------------
    // Blobs live under <JusPrin data dir>/attachments/<id>/<name>. The host
    // owns the semantic record; persistence owns only the bytes on disk.
    std::string attachments_dir() const;
    // Writes bytes to <JusPrin data dir>/relative_path (attachment paths are
    // caller-sanitized). Returns false when the write fails.
    bool write_attachment_blob(const std::string& relative_path, const std::string& bytes);
    // Reads an attachment blob back (empty when missing); used to rebuild image
    // previews after a reload without persisting them in state.json.
    std::string read_attachment_blob(const std::string& relative_path) const;
    // Removes an attachment's blob directory (relative to the JusPrin data
    // dir); used when a staged attachment is discarded.
    void remove_attachment_dir(const std::string& relative_dir);

    // A clean-sharing copy: the project without conversations or any other
    // auxiliary content.
    Workspace::CommandResult export_clean_copy(const std::string& file_path);

    // Storage locations resolved for the active managed or legacy project.
    std::string jusprin_data_dir() const;
    std::string state_file_path() const;
    std::string recovery_dir() const; // empty when disabled or no identity

private:
    void notify_document_replaced();
    void on_workspace_changed(const Workspace::WorkspaceChanged& change);
    void on_edit(const Workspace::WorkspaceEdit& edit);
    bool heal_if_directory_moved();
    void adopt_current_project(bool in_place_reset);
    void start_fresh_identity();
    void write_state_to(const std::string& directory) const;
    void write_recovery_meta() const;
    void load_recovery_meta();

    Workspace::IWorkspace&           m_workspace;
    Config                           m_config;
    Workspace::WorkspaceSubscription m_subscription;
    Workspace::WorkspaceSubscription m_edit_subscription;
    ProjectStateDocument             m_document;

    std::function<void()>                   m_document_replaced;
    std::function<void(const ChangeEntry&)> m_change_added;
    struct LedgerObservers;
    std::shared_ptr<LedgerObservers>        m_ledger_observers;

    // Attachment bytes of an in-memory session, by the same relative path a
    // project session writes on disk.
    std::map<std::string, std::string> m_blobs;

    std::string m_attached_aux_dir;
    std::string m_draft;
    bool        m_dirty{false};
    bool        m_attached{false};
    bool        m_boundary_pending{false};
    bool        m_managed_restore_active{false};
};

} // namespace Slic3r::GUI::JusPrin::Agent
#pragma once

// Native side of the typed Agent bridge. The host owns the runtime
// conversation flow, consumes the workspace contract for context, and talks
// to the page only through versioned JSON envelopes handed to a send
// callback. Conversation and timeline state is document-backed: the
// ProjectPersistence document is the durable record, and every mutation goes
// through it, so an explicit project save, a reload, or a crash recovery all
// reconstruct the same state. GUI-free and deterministic: streaming and tool
// execution advance only when the owner calls the pump methods.
//
// The page renders host state and submits typed requests; it never owns an
// editable copy of the conversation or project. Reload reconstruction works
// by re-running the handshake: every hello is answered with the complete
// state.

#include "AgentProtocol.hpp"
#include "AgentService.hpp"
#include "AgentSetup.hpp"
#include "ProjectPersistence.hpp"
#include "ToolExecutionCoordinator.hpp"
#include "slic3r/GUI/JusPrin/Mcp/McpConfigFile.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"

#include <deque>
#include <filesystem>
#include <functional>
#include <map>
#include <optional>
#include <set>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Mcp { class McpRuntime; struct CatalogItem; }

namespace Slic3r::GUI::JusPrin::Agent {

class AgentHost
{
public:
    using SendFn = std::function<void(const std::string& envelope_json)>;

    AgentHost(Workspace::IWorkspace& workspace,
              ProjectPersistence&    persistence,
              AgentAvailability      availability,
              bool                   dark_appearance,
              AgentServicePtr        agent = {},
              AgentSetupServicePtr   setup = {});
    ~AgentHost();

    AgentHost(const AgentHost&) = delete;
    AgentHost& operator=(const AgentHost&) = delete;

    void set_send(SendFn send);

    // -- Sessions with a subject of their own --------------------------------
    // The host is the project's conversation unless an owner says otherwise.
    // A panel whose conversation is about something else -- the printer panel
    // on Home -- supplies the four things that differ: what the model is told
    // and may call, the turn that opens the conversation, the page messages of
    // its own surface, and the state its surface pins above the thread.

    // Stamped on every request this host makes.
    void set_session_profile(AgentSessionProfile profile) { m_session_profile = std::move(profile); }
    // The model answers next, from the conversation as it stands. A file
    // report supplies its note ID so that its data belongs to this turn;
    // other app-initiated turns have no message of their own.
    void start_turn(const std::string& source_message_id = {});
    // Answers a page message this host does not know. Returning false leaves
    // it to the host, which reports it as a type outside the protocol.
    using PageMessageHandler = std::function<bool(const std::string& type, const nlohmann::json& payload)>;
    void set_page_message_handler(PageMessageHandler handler) { m_page_message_handler = std::move(handler); }
    // Carried in every `state` snapshot as `session`, so a page that reloads
    // is told what its surface shows without asking the subject itself.
    void set_session_state_provider(std::function<nlohmann::json()> provider)
    {
        m_session_state_provider = std::move(provider);
    }
    // Shell navigation is transient view state. It travels with a full state
    // snapshot so a WebView reload can restore the correct Back action.
    void set_navigation_state_provider(std::function<nlohmann::json()> provider)
    {
        m_navigation_state_provider = std::move(provider);
    }
    void set_restore_points_provider(std::function<nlohmann::json()> provider)
    {
        m_restore_points_provider = std::move(provider);
    }
    void refresh_page_state() { send_state(); }
    // Decodes an image attachment's raw bytes into a small thumbnail data
    // URL, for the composer/thread preview only -- the model still gets the
    // untouched original, read separately for its own context. Empty (the
    // default, and what every GUI-free test leaves it) means no preview:
    // decoding an arbitrary image needs wx, which this host's own build
    // does not link, so the real app wires this after construction and the
    // tests wire a fake.
    using ImageThumbnailFn = std::function<std::string(const std::string& bytes)>;
    void set_image_thumbnail_maker(ImageThumbnailFn maker) { m_image_thumbnail_maker = std::move(maker); }
    // Sends one envelope of a type this protocol declares. The subject uses
    // it to push its own state between snapshots.
    void send_page_envelope(const std::string& type, const nlohmann::json& payload);
    // Runs the session's own tools, inside the coordinator's approval and
    // state machine. Anything it leaves unhandled stays with the host.
    void set_session_tool_executor(ToolExecutionCoordinator::ExtensionExecutor executor)
    {
        m_session_tool_executor = std::move(executor);
    }
    // Checks a call to the session's own tools before its card or its run.
    void set_session_tool_preflight(ToolExecutionCoordinator::ExtensionPreflight preflight);
    // What the model reads back for a call to the session's own tools, in
    // place of the host's envelope; nullopt keeps the host's.
    using ToolOutputFormatter = std::function<std::optional<nlohmann::json>(const ToolActivity& activity)>;
    void set_session_tool_output(ToolOutputFormatter formatter) { m_session_tool_output = std::move(formatter); }
    // What the person typed into an approval card beside approving it -- a
    // credential the model must never see -- handed once to the executor of
    // that action and then forgotten. It is kept out of the activity, every
    // envelope, every note and the document.
    std::optional<nlohmann::json> take_decision_input(const std::string& action_id);
    // Appends a message the agent is shown as having said, without asking the
    // model for it: a panel whose opening line is always the same. Returns
    // its id so the owner can anchor what it draws underneath.
    std::string post_assistant_message(const std::string& text);

    // Invoked after every successful hello handshake (initial load and every
    // reload); the owner uses it to cancel its connection deadline.
    void set_handshake_listener(std::function<void()> listener) { m_handshake_listener = std::move(listener); }
    // A completed, failed, or stopped reply is a document durability boundary.
    void set_turn_boundary_callback(std::function<void()> callback) { m_turn_boundary_callback = std::move(callback); }

    // Invoked once, right after pump_setup() persists a verified credential
    // and installs the newly connected agent. A throwaway setup-only host
    // (e.g. one embedded in a native dialog rather than the docked panel)
    // uses this to know when to hand control back to its owner instead of
    // polling availability().
    void set_setup_completed_listener(std::function<void()> listener) { m_setup_completed_listener = std::move(listener); }

    // Call when the page starts (re)loading; the host requires a new
    // handshake before any other message and pauses stream delivery until the
    // page reconnects. Conversation state is unaffected.
    void reset_page();

    // One JSON envelope from the page.
    void on_page_message(const std::string& envelope_json);

    void set_appearance(bool dark);
    void set_availability(AgentAvailability availability);
    void set_agent(AgentServicePtr agent, AgentAvailability availability);
    // Opens the page's setup flow; held until the next handshake when the
    // page is not connected yet.
    void request_setup();

    bool              handshake_complete() const { return m_handshake; }
    bool              stream_active() const { return m_stream.has_value(); }
    AgentAvailability availability() const { return m_availability; }

    // Emits the next assistant delta (or the terminal event) when a stream is
    // active and the page is connected. The owner paces this from a timer;
    // tests call it directly.
    void pump_stream();

    // Advances native execution while the page is connected or MCP is enabled,
    // drains the MCP mailbox, and gives dirty state its throttled flush.
    void pump_tools();

    // Releases a finished credential check. A verified credential is
    // persisted and its already-connected service installed here, so setup
    // succeeding and the Agent becoming available are one step.
    void pump_setup();

    ToolExecutionCoordinator&       tools() { return m_tools; }
    const ToolExecutionCoordinator& tools() const { return m_tools; }
    ProjectPersistence&             persistence() { return m_persistence; }
    // Opt-in local adapter; its lifetime is independent of the page handshake.
    void start_mcp(const std::string& discovery_path);
    // Where the facts a person states about their printers are kept: app
    // data, not the project. Without it the tools that read or write them say
    // the operation is unavailable.
    void set_printer_facts_path(std::string path) { m_product_state.set_facts_path(std::move(path)); }
    const Mcp::McpRuntime* mcp() const { return m_mcp.get(); }

    struct McpConnectSettings
    {
        std::string helper_path;
        std::string launcher_path;
        std::vector<std::string> launch_arguments;
        std::string startup_error;
        std::filesystem::path home;
        std::filesystem::path config_home;
        bool windows{false};
    };
    using McpCliDone = std::function<void(bool success, std::string diagnostic)>;
    using McpCliRunner = std::function<void(const std::vector<std::string>& arguments, McpCliDone done)>;
    void configure_mcp_connect(McpConnectSettings settings);
    void set_mcp_cli_runner(McpCliRunner runner);
    // Reveals one file in the desktop's file manager. The host stays GUI-free,
    // so the wx side supplies the implementation the way it does the CLI
    // runner above.
    using RevealPathFn = std::function<void(const std::string& path)>;
    void set_reveal_path_handler(RevealPathFn reveal);

    // The active conversation's messages, straight from the document.
    std::vector<ConversationMessage> conversation() const;

    // Appends one host-authored note to the active conversation: a short
    // factual line about something the shell just changed. It is durable like
    // any message, renders without a bubble, starts no reply, and is never
    // sent to the model. `swatch`, when given, is a colour ("#RRGGBB") the
    // line leads with -- the filament a change landed on. Returns the note's ID.
    std::string post_note(const std::string& text, const std::string& swatch = {});

    // A file the person opened or imported has finished loading. The report
    // joins the conversation as a note the model reads and the page does not
    // draw, and the Agent speaks first about it. When the Agent can't, the
    // page draws the report's messages as a card instead. A reopened project
    // that brought its conversation back is spoken about only when OrcaSlicer
    // said something while loading it.
    void on_file_loaded(const Workspace::LoadReport& report);

    // Diagnostics for the internal-connection error surface.
    std::uint64_t messages_sent() const { return m_messages_sent; }
    std::uint64_t messages_received() const { return m_messages_received; }

private:
    struct ActiveStream
    {
        std::string         conversation_id;
        ConversationMessage message; // authoritative in-progress copy
        int                 next_seq{0};
    };

    struct PendingToolContinuation
    {
        std::string call_id;
        std::string conversation_id;
        std::string user_message_id;
    };

    void send_envelope(const char* type, const std::string& payload_json, const std::string& correlation_id = {});
    void send_bridge_error(const std::string& code, const std::string& message, const std::string& correlation_id = {});
    void send_state(const std::string& correlation_id = {});
    void send_context();
    void send_conversations();

    // Reads one page envelope and routes it. Split from on_page_message so a
    // fault anywhere in reading or handling a message is caught in one place,
    // with that message's own type and id still in hand.
    void dispatch_page_message(const std::string& envelope_json, std::string& type, std::string& envelope_id);

    void handle_hello(const std::string& envelope_id, const std::string& payload_json);
    void handle_user_message(const std::string& envelope_id, const std::string& payload_json);
    void handle_stop(const std::string& payload_json);
    void handle_retry(const std::string& envelope_id, const std::string& payload_json);
    void handle_tool_decision(const std::string& envelope_id, const std::string& payload_json);
    void handle_tool_cancel(const std::string& envelope_id, const std::string& payload_json);
    void handle_create_conversation(const std::string& envelope_id, const std::string& payload_json);
    void handle_switch_conversation(const std::string& envelope_id, const std::string& payload_json);
    void handle_rename_conversation(const std::string& envelope_id, const std::string& payload_json);
    void handle_delete_conversation(const std::string& envelope_id, const std::string& payload_json);
    void handle_draft_update(const std::string& payload_json);
    void handle_attach_file(const std::string& envelope_id, const std::string& payload_json);
    void handle_remove_attachment(const std::string& envelope_id, const std::string& payload_json);
    void handle_setup_check_key(const std::string& envelope_id, const std::string& payload_json);
    void handle_setup_cancel();
    void handle_mcp_catalog(const std::string& envelope_id);
    void handle_mcp_preview(const std::string& envelope_id, const std::string& payload_json);
    void handle_mcp_connect(const std::string& envelope_id, const std::string& payload_json);
    void handle_reveal_path(const std::string& envelope_id, const std::string& payload_json);
    // The catalog as the connect settings currently describe it. Every MCP
    // handler resolves a tool id through this, so none of them takes a path
    // from the page.
#pragma once

// Versioned JSON bridge protocol between the native AgentHost and the local
// React Agent page. The canonical protocol description shared with the web
// package is resources/jusprin/agent/protocol.json; the contract tests assert
// that these constants and that file agree. This header is GUI-free.

#include <cstdint>
#include <optional>
#include <string>
#include <vector>

namespace Slic3r::GUI::JusPrin::Agent {

namespace Protocol {

// The page and host ship in the same build, so this only guards a page/host
// mismatch at runtime — which cannot happen pre-release. It stays 1 through
// development (additive features are negotiated via the capabilities list
// below) and bumps only after go-live, on a breaking change to an existing
// message's shape.
inline constexpr int         kVersion = 1;
inline constexpr const char* kName    = "jusprin-agent-bridge";

inline const std::vector<std::string>& capabilities()
{
    static const std::vector<std::string> values{"streaming",   "stop",        "retry",
                                                 "context",     "appearance",  "tools",
                                                 "conversations", "attachments",
                                                 "manufacturing_history", "agent_setup", "conversation_management",
                                                 "mcp_setup", "system_notes", "reveal_path", "change_log",
                                                 "printer_panel", "file_reports"};
    return values;
}

// Messages the page may send to the host.
inline constexpr const char* kHello              = "hello";
inline constexpr const char* kStateRequest       = "state_request";
inline constexpr const char* kUserMessage        = "user_message";
inline constexpr const char* kStopGeneration     = "stop_generation";
inline constexpr const char* kRetryMessage       = "retry_message";
inline constexpr const char* kToolDecision       = "tool_decision";
inline constexpr const char* kToolCancel         = "tool_cancel";
inline constexpr const char* kCreateConversation = "create_conversation";
inline constexpr const char* kSwitchConversation = "switch_conversation";
inline constexpr const char* kRenameConversation = "rename_conversation";
inline constexpr const char* kDeleteConversation = "delete_conversation";
inline constexpr const char* kConversationsUpdated = "conversations_updated";
inline constexpr const char* kDraftUpdate        = "draft_update";
inline constexpr const char* kAttachFile         = "attach_file";
inline constexpr const char* kRemoveAttachment   = "remove_attachment";
inline constexpr const char* kSetupCheckKey      = "setup_check_key";
inline constexpr const char* kSetupCancel        = "setup_cancel";
inline constexpr const char* kMcpCatalog         = "mcp_catalog";
inline constexpr const char* kMcpPreview         = "mcp_preview";
inline constexpr const char* kMcpConnect         = "mcp_connect";
// Reveal one host-known file in the desktop's file manager. The page names a
// catalog tool, never a path: the host resolves it, so nothing the page can
// say reaches the shell.
inline constexpr const char* kRevealPath         = "reveal_path";

// Messages the host sends to the page.
inline constexpr const char* kHelloAck           = "hello_ack";
inline constexpr const char* kHelloReject        = "hello_reject";
inline constexpr const char* kState              = "state";
inline constexpr const char* kContext            = "context";
inline constexpr const char* kAppearance         = "appearance";
inline constexpr const char* kAgentStatus        = "agent_status";
inline constexpr const char* kMessageAdded       = "message_added";
inline constexpr const char* kAssistantStarted   = "assistant_started";
inline constexpr const char* kAssistantDelta     = "assistant_delta";
inline constexpr const char* kAssistantCompleted = "assistant_completed";
inline constexpr const char* kAssistantFailed    = "assistant_failed";
inline constexpr const char* kAssistantStopped   = "assistant_stopped";
inline constexpr const char* kToolActivity       = "tool_activity";
inline constexpr const char* kBridgeError        = "bridge_error";
inline constexpr const char* kAttachmentUpdated  = "attachment_updated";
inline constexpr const char* kSetupStatus        = "setup_status";
inline constexpr const char* kMcpStatus          = "mcp_status";
// One new change log entry; the full list travels in `state`.
inline constexpr const char* kChangeAdded        = "change_added";
// Asks the page to open its own setup flow, as its "Set up the agent" button
// does; sent when another JusPrin surface sends the person there.
inline constexpr const char* kOpenSetup          = "open_setup";
// The printer panel's own: what its surface shows above and inside the
// thread, a tap on one of the cards it draws there, and the model's
// instructions, which the page writes.
inline constexpr const char* kPrinterSession      = "printer_session";
inline constexpr const char* kPrinterAction       = "printer_action";
inline constexpr const char* kPrinterInstructions = "printer_instructions";
// Its opening line, which the page writes and the app posts.
inline constexpr const char* kPrinterOpening      = "printer_opening";
// The filament chat's instructions, which the page writes from the facts
// the app sends as the state's session.
inline constexpr const char* kFilamentInstructions = "filament_instructions";
inline constexpr const char* kShellAction          = "shell_action";
// What the model is told when a file report opens a turn, which the page
// writes.
inline constexpr const char* kFileReportInstructions = "file_report_instructions";

} // namespace Protocol

// The Agent service and the bridge are different failures: Unavailable is the
// clean "service not configured" empty state, while bridge errors are internal
// connection failures surfaced separately.
enum class AgentAvailability { Ready, Unavailable };

struct AgentError
{
    std::string code;
    std::string message;
    bool        retryable{false};
};

// Note is the host's own voice: a short factual line the shell posts when it
// changes something the person should see in the thread. It is not a turn --
// no reply follows it, it is never sent to the model, and it renders without a
// bubble. Added additively; the capability list advertises it.
enum class MessageRole : std::uint8_t { User, Assistant, Note };
enum class MessageState : std::uint8_t { Complete, Streaming, Failed, Stopped };

struct ConversationMessage
{
    std::string               id;                // host-assigned, stable across reloads
    MessageRole               role{MessageRole::User};
    MessageState              state{MessageState::Complete};
    std::string               text;
    std::string               client_message_id; // user messages: page-supplied dedup ID
    std::string               in_reply_to;       // assistant messages: the user message ID
    std::optional<AgentError> error;
    int                       attempt{1};
    std::vector<std::string>  attachment_ids;    // user messages: sent attachment IDs
    std::string               swatch;            // notes: a colour that leads the line, "#RRGGBB"
    // Notes: a file's load report (JSON), which the model reads; the page
    // draws it only as a card, when the Agent could not speak about it.
    std::string               file_report;
    bool                      file_report_card{false};
};

} // namespace Slic3r::GUI::JusPrin::Agent

