            cancelCheck();
            setSetupScreen('chooser');
          }}
        />
      );
    return <AgentNotConfiguredPane onSetUp={openSetup} fileReports={fileReportNotes} />;
  };

  if (printerPanel) {
    const session = state.session;
    const printerAction = (action: string) => client.send('printer_action', { action });
    // No tool closes the panel for the model: the person decides when they
    // are done, with Back or by opening the printer's own settings.
    const back = () => {
      const started = state.messages.some((message) => message.role === 'user') ||
        state.attachments.some((attachment) => attachment.state === 'staged') || printerDraft.current.trim() !== '';
      if (started) setConfirmPrinterClose(true);
      else printerAction('close');
    };
    return (
      // The whole panel takes a photo, not only the composer: a picture of
      // the printer is dropped where the person is looking.
      <div
          const key = planKey(activity);
          const found = key ? externalPlans.get(key) : undefined;
          // A plan of one change is decided like any other call.
          const members = found && found.length > 1 ? found : undefined;
          if (members && members[0].actionId !== activity.actionId) return null;
          return members
            ? <PlanActivityCard key={activity.actionId} members={members} headline={planHeadline(state.toolActivities)}
                onDecision={sendToolDecision} onCancel={sendToolCancel} />
            : <ToolActivityCard key={activity.actionId} activity={activity}
                onDecision={sendToolDecision} onCancel={sendToolCancel} />;
        })}
      </section>}
      {view === 'list' && !state.navigation.focused && chatList}
      <div className="chat-content" hidden={view === 'list'}>
      {notConfigured && state.conversations.length === 1 && view !== 'setup' && !state.navigation.focused ? (
        <AgentNotConfiguredHeader onCollapse={collapseAgentPane} />
      ) : state.navigation.focused ? (
        <header className="chat-header printer-header">
          <button type="button" className="printer-link-button printer-back-link" aria-label={state.navigation.returnLabel ?? 'Back to Prepare'}
            onClick={() => { if (view === 'setup') closeSetup(); else returnToWorkspace(); }}><span className="jp-icon jp-icon-chevron-left" aria-hidden="true" /> Back</button>
          {view !== 'setup' && <button type="button" className="printer-link-button"
            onClick={() => client.send('shell_action', { action: 'open_filament_settings' })}>Open filament settings</button>}
          <AgentPaneToggle onCollapse={collapseAgentPane} />
        </header>
      ) : (
        <>
          <ChatHeader key={`header-${state.context?.sessionId}-${state.activeConversationId}`} title={activeChat?.title || 'New chat'} busy={busy || pendingAction}
            onBack={() => { collapseSetup(); if (view === 'setup') closeSetup(); else { client.send('state_request', {}); setView('list'); } }}
            onCreate={createChat}
            onRename={(title) => client.send('rename_conversation', { conversationId: state.activeConversationId, title })}
            onDelete={() => { client.send('delete_conversation', { conversationId: state.activeConversationId }); setView('list'); }}
            onCollapse={collapseAgentPane} />
          {view === 'chat' && !notConfigured && state.context && (
            // The card sits in its own pinned band above the thread, as the
            // design has it: the band is the canvas the tinted card sits on.
            <div className="pinned-setup">
              <SetupCard context={state.context} expanded={setupExpanded} working={busy}
                onToggle={() => setSetupExpanded((open) => !open)} />
            </div>
          )}
        </>
      )}
      {!notConfigured && connected && (
        <ConnectedBanner
          provider={connected.provider}
          warning={connected.warning}
          onDismiss={() => setConnected(null)}
        />
      )}
      {body()}
      {!(state.navigation.focused && notConfigured) && <div hidden={view === 'setup'}><Composer
        key={`composer-${state.context?.sessionId}-${state.activeConversationId}`}
        disabled={unavailable}
        disabledReason={notConfigured ? 'ask, or steer this chat…' : unavailable ? 'The Agent is not available' : undefined}
        placeholder={state.navigation.focused ? 'Ask about this filament or request a change…' : undefined}
        streaming={streaming}
        initialText={state.draft}
        attachments={stagedAttachments}
        onSend={sendMessage}
        onStop={() => {
          if (state.streamingMessageId) client.send('stop_generation', { messageId: state.streamingMessageId });
        }}
        onAttachFiles={attachFiles}
        onRemoveAttachment={removeAttachment}
        onTyping={collapseSetup}
        onDraftChange={(text) => client.send('draft_update', { text })}
        draftDebounceMs={draftDebounceMs}
      /></div>}
      </div>
    </div>
  );
}

export function ChatList({ conversations, activeId, busy, agentUnavailable, onSwitch, onCreate, onConfigure, onCollapse }: {
  conversations: ConversationInfo[];
  activeId: string;
  busy: boolean;
  agentUnavailable: boolean;
  onSwitch: (id: string) => void;
  onCreate: () => void;
  onConfigure: () => void;
  onCollapse: () => void;
}) {
  const [now, setNow] = useState(() => new Date());
  useEffect(() => { const timer = window.setInterval(() => setNow(new Date()), 60000); return () => clearInterval(timer); }, []);
  return <section className="chat-list-pane" aria-label="Project chats">
    <header className="chat-list-header"><h1>Chats</h1><NewChat busy={busy} onCreate={onCreate} />
      <AgentPaneToggle onCollapse={onCollapse} /></header>
    <div className="chat-list-scroll">
      {conversations.length === 0 && <p className="chat-list-empty">No chats yet. Start a new chat about this project.</p>}
      {conversations.map((chat) => {
        const preview = (chat.preview || 'No messages yet').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1').replace(/[*#`_]/g, '').replace(/\s+/g, ' ');
        return <button key={chat.id} className={`chat-list-row${chat.id === activeId ? ' selected' : ''}`}
          aria-current={chat.id === activeId ? 'true' : undefined} aria-label={`Open chat: ${chat.title}`}
          disabled={busy && chat.id !== activeId} onClick={() => onSwitch(chat.id)}>
          <span className="chat-list-row-top"><ChatIcon /><strong title={chat.title}>{chat.title}</strong>
            <time dateTime={chat.updatedAt || chat.createdAt} title={chat.updatedAt || chat.createdAt}>{chatTimestamp(chat.updatedAt || chat.createdAt, now)}</time></span>
          <span className="chat-list-preview">{preview}</span>
        </button>;
      })}
    </div>
    <footer className="chat-list-footer">
      <button className="configure-agent" onClick={onConfigure} disabled={busy}>
        <span className="jp-icon jp-icon-settings" aria-hidden="true" />
        <span>
          <strong>{agentUnavailable ? 'Set up the agent' : 'Configure Agent'}</strong>
          <small>{agentUnavailable ? 'Connect an Agent to continue this conversation' : 'Adjust defaults, models, and slice preferences'}</small>
        </span>
      </button>
    </footer>
  </section>;
}

