export function ChatList({ conversations, activeId, busy, agentUnavailable, onSwitch, onCreate, onConfigure, onCollapse }: {
  conversations: ConversationInfo[];
  activeId: string;
  busy: boolean;
  agentUnavailable: boolean;
  onSwitch: (id: string) => void;
  onCreate: () => void;
  onConfigure: () => void;
  onCollapse: () => void;
