Workspace::PrinterFactsStore* AgentHost::DocumentProductState::facts() const
{
    if (!m_facts && !m_facts_path.empty())
        m_facts = std::make_unique<Workspace::PrinterFactsStore>(Workspace::PrinterFactsStore::Config{m_facts_path, {}});
