  connectionDetail?: string;
  agentStatus: AgentStatus;
  appearance: Appearance;
  conversations: ConversationInfo[];
  activeConversationId: string;
  messages: Message[];
  streamingMessageId: string | null;
  conversationBusy: boolean;
  toolActivities: ToolActivityInfo[];
  builds: BuildInfo[];
  exportedCopies: ExportedCopyInfo[];
  physicalPrints: PhysicalPrintInfo[];
  changes: ChangeInfo[];
  restorePoints: RestorePointInfo[];
  draft: string;
  // Staged (composer) and sent (history) attachments, keyed by id in the UI.
  attachments: AttachmentInfo[];
  context: WorkspaceContext | null;
  // What the printer panel shows above and inside its thread; null in the
  // project's own conversation.
  session: PrinterSessionPayload | null;
  // The filament chat's, in its place.
  filamentSession: FilamentSessionPayload | null;
  navigation: { focused: boolean; returnLabel?: string };
  // Progress of a credential check. The host owns it; the page only mirrors
  // it, so a reload cannot leave a check looking live when it is not.
  setup: SetupStatusPayload;
  mcpCatalog: McpCatalogPayload | null;
  mcpPreview: McpPreviewPayload | null;
  mcpStatus: McpStatusPayload;
  // Counts the host's requests to open setup; the app opens it on each change.
  setupRequests: number;
  // Set when a delta arrived out of order; the app answers by requesting a
  // full state resync from the host.
  needsResync: boolean;
  diagnostics: string[];
}

export const initialState: AgentUiState = {
  connection: 'connecting',
  agentStatus: 'ready',
  appearance: 'light',
  conversations: [],
  activeConversationId: '',
  messages: [],
  streamingMessageId: null,
  conversationBusy: false,
  toolActivities: [],
  builds: [],
  exportedCopies: [],
  physicalPrints: [],
  changes: [],
  restorePoints: [],
  draft: '',
  attachments: [],
  context: null,
  setup: { phase: 'idle' },
  mcpCatalog: null,
  mcpPreview: null,
  mcpStatus: { phase: 'idle' },
  session: null,
  filamentSession: null,
  navigation: { focused: false },
  setupRequests: 0,
  needsResync: false,
  diagnostics: [],
};

export type Action =
  | { kind: 'connection'; state: ConnectionState; detail?: string }
  | { kind: 'host'; envelope: Envelope }
  | { kind: 'resync-requested' };

function fromWire(message: WireMessage): Message {
  return { ...message, lastSeq: -1 };
}

function upsert(messages: Message[], incoming: Message): Message[] {
  const index = messages.findIndex((m) => m.id === incoming.id);
  if (index < 0) return [...messages, incoming];
  const next = messages.slice();
  next[index] = incoming;
  return next;
}

function withDiagnostic(state: AgentUiState, line: string): AgentUiState {
  return { ...state, diagnostics: [...state.diagnostics.slice(-19), line] };
}

export function reducer(state: AgentUiState, action: Action): AgentUiState {
  switch (action.kind) {
    case 'connection':
      return { ...state, connection: action.state, connectionDetail: action.detail };
    case 'resync-requested':
      return { ...state, needsResync: false };
    case 'host':
      return applyHostEnvelope(state, action.envelope);
  }
}

function applyHostEnvelope(state: AgentUiState, envelope: Envelope): AgentUiState {
  const payload = envelope.payload as Record<string, unknown>;
  switch (envelope.type) {
    case 'hello_ack': {
      const agent = payload.agent as { status: AgentStatus } | undefined;
      const appearance = payload.appearance as Appearance | undefined;
      return {
        ...state,
        agentStatus: agent?.status ?? state.agentStatus,
        appearance: appearance ?? state.appearance,
      };
    }
    case 'hello_reject':
      return state; // connection state handled by the client
    case 'state': {
      const full = envelope.payload as StatePayload;
      return {
        ...state,
        agentStatus: full.agent.status,
        appearance: full.appearance,
        conversations: full.conversations ?? [],
        activeConversationId: full.activeConversationId ?? '',
        messages: full.conversation.map(fromWire),
        streamingMessageId: full.streamingMessageId,
        conversationBusy: full.conversationBusy ?? full.streamingMessageId !== null,
        toolActivities: full.toolActivities ?? [],
        builds: full.builds ?? [],
        exportedCopies: full.exportedCopies ?? [],
        physicalPrints: full.physicalPrints ?? [],
        changes: full.changes ?? [],
        restorePoints: full.restorePoints ?? [],
        draft: full.draft ?? '',
        attachments: full.attachments ?? [],
        context: full.context,
        session: full.session && !('kind' in full.session) ? full.session : null,
        filamentSession: full.session && 'kind' in full.session ? full.session : null,
        navigation: full.navigation ?? { focused: false },
        // A full state answers a fresh handshake; any check that was in
        // flight before belonged to the previous page.
        setup: { phase: 'idle' },
        mcpStatus: { phase: 'idle' },
        needsResync: false,
      };
    }
    case 'context':
      return { ...state, context: payload.context as WorkspaceContext };
    case 'printer_session':
      return { ...state, session: envelope.payload as PrinterSessionPayload };
    case 'conversations_updated':
      return { ...state, conversations: payload.conversations as ConversationInfo[], conversationBusy: payload.busy as boolean };
    case 'appearance':
      return { ...state, appearance: payload.appearance as Appearance };
    case 'agent_status':
      return { ...state, agentStatus: payload.status as AgentStatus };
    case 'setup_status':
      return { ...state, setup: envelope.payload as SetupStatusPayload };
    case 'open_setup':
      return { ...state, setupRequests: state.setupRequests + 1 };
    case 'mcp_catalog':
      return { ...state, mcpCatalog: envelope.payload as McpCatalogPayload };
    case 'mcp_preview':
      return { ...state, mcpPreview: envelope.payload as McpPreviewPayload };
    case 'mcp_status':
      return { ...state, mcpStatus: envelope.payload as McpStatusPayload };
    case 'message_added': {
      const message = fromWire(payload.message as WireMessage);
      return { ...state, messages: upsert(state.messages, message) };
    }
    case 'assistant_started': {
      const id = payload.messageId as string;
      const existing = state.messages.find((m) => m.id === id);
      const started: Message = existing
        ? { ...existing, state: 'streaming', text: '', error: undefined, attempt: (payload.attempt as number) ?? existing.attempt, lastSeq: -1 }
        : {
            id,
            role: 'assistant',
            state: 'streaming',
            text: '',
            attempt: (payload.attempt as number) ?? 1,
    if (state.needsResync) {
      client.send('state_request', {});
      dispatch({ kind: 'resync-requested' });
    }
  }, [state.needsResync, client]);

  // The composer shows staged attachments plus any that failed to attach, so a
  // rejection stays visible until the user dismisses it; only staged ones are
  // actually sent.
  const stagedAttachments = state.attachments.filter(
    (attachment) => attachment.state === 'staged' || attachment.state === 'error',
  );

  const sendMessage = (text: string, includeStagedAttachments = true) => {
    // From the ref, not this render: the test hook keeps the first render's
    // sendMessage, which would otherwise never see a later attachment.
    const attachmentIds = includeStagedAttachments
      ? stateRef.current.attachments.filter((a) => a.state === 'staged').map((a) => a.id)
      : [];
    client.send('user_message', { clientMessageId: nextClientMessageId(), text, attachmentIds });
  };

  const attachFiles = (files: File[], source: AttachmentSource) => {
    for (const file of files) {
      readAsDataUrl(file)
        .then((dataUrl) => {
          client.send('attach_file', {
            clientAttachmentId: nextClientAttachmentId(),
            name: file.name,
            mime: file.type,
            source,
            dataBase64: dataUrl,
          });
        })
        .catch(() => {
          // A file the browser could not read never becomes a staged
          // attachment; the host only sees files it can decode.
        });
    }
  };

  const removeAttachment = (attachmentId: string) => {
    client.send('remove_attachment', { attachmentId });
  };

  // `input` is what the person typed into the card itself, such as the
  // printer panel's access code: the app hands it to the action and nowhere
  // else.
  const sendToolDecision = (actionId: string, decision: 'approve' | 'reject', input?: { credential: string }) => {
    client.send('tool_decision', input ? { actionId, decision, input } : { actionId, decision });
  };

  const sendToolCancel = (actionId: string) => {
    client.send('tool_cancel', { actionId });
  };

  const checkKey = (provider: string, apiKey: string) => {
    client.send('setup_check_key', { provider, apiKey });
  };

  const cancelCheck = () => {
  const stateRef = useRef<AgentUiState>(state);
  stateRef.current = state;

  // Which setup screen the dock is showing. This is page-local on purpose:
  // the host cares which credentials it was asked to check, not which panel
  // is on screen, so navigating setup costs no bridge traffic.
  const [setupScreen, setSetupScreen] = useState<'offer' | 'chooser' | 'apiKey' | 'localTool'>('offer');
  const [view, setView] = useState<'chat' | 'list' | 'setup'>('chat');
  // The setup card's expansion is a temporary layer over the thread, so it is
  // page-local and closes on its own the moment the user does something else.
  const [setupExpanded, setSetupExpanded] = useState(false);
  // Every way out of this chat closes the card's expansion. Kept explicit
  // rather than derived from an effect: an effect on (chat, view) re-ran
  // whenever the host resent state and re-closed the card mid-click.
  const collapseSetup = () => setSetupExpanded(false);
  const [commandError, setCommandError] = useState<string | null>(null);
  const setupReturn = useRef<'chat' | 'list'>('chat');
  // The one-time confirmation after setup succeeds. The page knows what it
  // just submitted, so this needs nothing from the host.
  const [connected, setConnected] = useState<{ provider: string; warning?: string } | null>(null);

  const client = useMemo(() => {
    const created: BridgeClient = new BridgeClient({
      getTransport,
      handshakeTimeoutMs,
      transportRetryMs,
      transportRetryLimit,
      onConnectionChange: (connection, detail) => dispatch({ kind: 'connection', state: connection, detail }),
      onEnvelope: (envelope: Envelope) => {
        if (envelope.type === 'bridge_error') {
          const payload = envelope.payload as { code?: string; message?: string };
          setCommandError(payload.message ?? 'The action could not be completed.');
          // The host restarts after a reload on its side; if it forgot us,
          // simply shake hands again.
          if (payload.code === 'handshake_required') created.retry();
        }
        dispatch({ kind: 'host', envelope });
      },
    });
    return created;
    // The transport is fixed for the lifetime of the page.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    client.start();
  }, [client]);

  useEffect(() => {
    applyAppearance(state.appearance);
  }, [state.appearance]);

  // The printer panel's first line, which the model is shown as having said:
  // written here, posted by the app, once per session. Before the
  // instructions, so the thread opens with it whatever is sent next.
  const sentOpening = useRef(false);
  useEffect(() => {
    if (!printerPanel || !state.session || state.connection !== 'connected') return;
    if (sentOpening.current || state.messages.length > 0) return;
    sentOpening.current = true;
    client.send('printer_opening', { text: opening(state.session) });

