.chat-dialog-shade { position: absolute; inset: 0; z-index: 4; display: flex; align-items: flex-start; justify-content: center; padding: 48px 16px 16px; background: var(--surface-subtle); overflow-y: auto; }
.chat-dialog { width: 100%; padding: 16px; border: 1px solid var(--border-subtle); border-radius: var(--radius-container); background: var(--surface-raised); }
.chat-dialog h2 { margin: 0 0 12px; font: var(--font-section); }
.chat-dialog p { overflow-wrap: anywhere; color: var(--text-secondary); font: var(--font-body); }
.chat-dialog label { display: block; font: var(--font-label); }
.chat-dialog input { width: 100%; margin-top: 4px; padding: 8px; font: inherit; color: var(--text-primary); background: var(--surface-canvas); border: 1px solid var(--border-strong); border-radius: var(--radius-standard); }
.chat-dialog-buttons { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.chat-error { display: flex; align-items: center; gap: 8px; flex: 0 0 auto; padding: 8px 12px; font: var(--font-label); color: var(--status-danger); background: var(--surface-raised); border-bottom: 1px solid var(--border-subtle); }
.chat-error > span { flex: 1; }

/* Measured from the Figma Design System component "Chat Bubble" (node 9-126),
   which has one property, Role, with the two variants below. Both hug their
   content; 75% is the point at which a turn still reads as one side of a
   conversation rather than as the whole column. */
.message {
  max-width: 75%;
  padding: 8px 12px;
  border-radius: var(--radius-container);
  /* Body Small, which the Chat Bubble component's text node carries. A turn
     is read in a 429px column and there are a lot of them, so the thread sets
     its own size rather than inheriting the page's Body. */
  font: var(--font-body-small);
  white-space: pre-wrap;
  overflow-wrap: break-word;
}

/* Role=User: surface/subtle fill, text/primary, 8px radius. The fill is the
   quiet one on purpose -- the user already knows what they said, and a
   saturated slab of action/primary every other turn drowns the agent's
   answer, which is the part being read. */
.message.user {
   conversation that is still there. */
.thread-dimmed {
  opacity: 0.3;
}

.notice {
  margin: 12px;
  padding: 12px;
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-container);
  background: var(--surface-raised);
}

.notice h2 {
  margin: 0 0 4px;
  font: var(--font-body-bold);
}

.notice p {
  margin: 0;
  color: var(--text-secondary);
  font: var(--font-label);
}

/* Conversation */
.external-actions {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 40%;
  overflow-y: auto;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);

