    for (const ConversationMessage& message : document.messages(viewed))
        conversation.push_back(message_json(message));

    json resume{{"status", "active"}};
    if (viewed != active) {
        resume["status"] = "unavailable";
        if (const auto checkpoint = document.chat_checkpoint(viewed)) {
            const std::string version = checkpoint->value("versionId", "");
            if (m_chat_version_exists && m_chat_version_exists(version)) {
                const bool same_model = m_current_chat_version && m_current_chat_version() == version;
                const bool same_planning = (*checkpoint)["planning"] == document.planning_snapshot();
                const bool same_intent = (*checkpoint)["summary"].value("setupIntent", "") == document.setup_intent(active);
                resume["status"] = same_model && same_planning && same_intent ? "unchanged" : "changed";
                resume["summary"] = (*checkpoint)["summary"];
                resume["savedAt"] = checkpoint->value("savedAt", "");
                resume["versionId"] = version;
            }
        }
    }

    // Stored history first, overlaid by live coordinator records (the live
    // record is fresher while an action runs). The project_open that closed
    // the last project is still live while it finishes; it is not this
    // project's.
    : m_root(std::move(root) / project_id), m_project_id(std::move(project_id))
{
    require(safe_component(m_project_id), "invalid project id");
    fs::create_directories(m_root / "versions");
    fs::create_directories(m_root / "resources");
    fs::create_directories(m_root / "pending");
    fs::create_directories(m_root / "materialized");
    fs::create_directories(m_root / "operations");
    lock();
    try {
        require(!fs::exists(m_root / "chat-restore.pending.json"),
                "an interrupted chat restoration requires recovery before this project can be edited");
        load_head();
        recover_uncommitted();
    } catch (...) {
        unlock();
        throw;
    }
}

void ProjectVersionStore::begin_chat_restore(const std::string& from_version,
                                              const std::string& to_version,
                                              const std::string& conversation_id)
{
    require(safe_component(from_version) && safe_component(to_version) && safe_component(conversation_id),
            "invalid chat restoration identity");
    const fs::path pending = m_root / "chat-restore.writing.json";
    checked_write(pending, json{{"fromVersion", from_version}, {"toVersion", to_version},
                                {"conversationId", conversation_id}}.dump(2));
    atomic_replace(pending, m_root / "chat-restore.pending.json");
}

