            "  var text = notes.length ? notes[0].textContent : '';"
            "  var probe = 'notes=' + notes.length + ';bubbles=' + bubbles.length + ';swatches=' + swatches.length + ';first=' + text;"
            "  window.__jusprinTest && window.__jusprinTest.setDraft(probe);"
